window.bookSummaryJSON = "<p>An ordinary girl, a dream to become extraordinary, and the powers that will lead her to change the world.<br> </p> <p>What would you do if you were invited to study at the Magical Arts Academy?</p> <p>Enroll, of course!<br> </p> <p>Join Isadora and her crew of magical misfits.</p> <p>Embark on a wild adventure today!<br> </p> <p>Omnibus 1 includes audiobooks 1-4 of the Magical Arts Academy:</p> <p></p> <ul> <li><i>First Spell</i></li> <li><i>Winged Pursuit</i></li> <li><i>Unexpected Agents</i></li> <li><i>Improbable Ally</i></li> </ul>"; 
